import{_ as e,o as d,c as s,a2 as a}from"./chunks/framework.wg_0zBou.js";const k=JSON.parse('{"title":"隧道协议（core ↔ agent）","description":"","frontmatter":{},"headers":[],"relativePath":"api/protocol.md","filePath":"api/protocol.md","lastUpdated":1795742187000}'),i={name:"api/protocol.md"};function o(r,t,h,c,n,l){return d(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="隧道协议-core-↔-agent" tabindex="-1">隧道协议（core ↔ agent） <a class="header-anchor" href="#隧道协议-core-↔-agent" aria-label="Permalink to &quot;隧道协议（core ↔ agent）&quot;">​</a></h1><p>core 与 agent 之间只有一种应用层协议：把 HTTP 请求/响应与 WebSocket 帧装进 JSON 帧。 stdio 模式按 NDJSON 分帧，reverse-ws 模式一条 WebSocket 文本消息一帧。http 传输不走隧道， core 直接反向代理真实 HTTP。</p><h2 id="帧格式" tabindex="-1">帧格式 <a class="header-anchor" href="#帧格式" aria-label="Permalink to &quot;帧格式&quot;">​</a></h2><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http-request&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;phase&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;head&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;r_xxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GET&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/api/v1/system/info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;stream&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>kind</th><th>方向</th><th>说明</th></tr></thead><tbody><tr><td><code>hello</code></td><td>worker → core</td><td>注册：<code>v</code>、<code>role</code>、<code>machineId</code>、<code>worker</code> 描述、<code>protocol</code> 限制</td></tr><tr><td><code>ping</code> / <code>pong</code></td><td>双向</td><td>心跳；core 每 10s 发 ping，30s 无任何帧判定断开</td></tr><tr><td><code>http-request</code></td><td>core → worker</td><td><code>phase=head</code> 带 method/url/headers；body 超过 512KiB 时用 <code>phase=chunk</code> 分块，<code>final=true</code> 结束</td></tr><tr><td><code>http-response</code></td><td>worker → core</td><td><code>phase=head</code> 带 status/headers；响应体流式回 <code>phase=chunk</code></td></tr><tr><td><code>ws-open</code></td><td>双向</td><td>core 请求打开流；worker 回 <code>accepted</code>/<code>status</code></td></tr><tr><td><code>ws-frame</code></td><td>双向</td><td><code>data</code> + <code>dataEncoding</code>（<code>utf8</code> 或 <code>base64</code>）</td></tr><tr><td><code>ws-close</code></td><td>双向</td><td>关闭码与发起方</td></tr></tbody></table><h2 id="约束" tabindex="-1">约束 <a class="header-anchor" href="#约束" aria-label="Permalink to &quot;约束&quot;">​</a></h2><ul><li>单帧上限 16 MiB；分块 512 KiB；单条 WS 消息上限 4 MiB。</li><li>请求按 <code>id</code> 多路复用；每个方向只允许一个写者（互斥）。</li><li>客户端断开时 core 发送 <code>http-request</code> + <code>phase=cancel</code>，worker 取消上游请求。</li><li>agent 的 WS 路由与直连 HTTP 共用同一张注册表（<code>agent.WSRegistry</code>），因此终端、容器日志 在三种传输下行为一致。</li><li><code>hello</code> 中的 <code>worker</code> 描述用于 core 侧「机器」页展示版本与能力；能力以 <code>GET /api/v1/system/info</code> 为准。</li></ul><h2 id="传输选择" tabindex="-1">传输选择 <a class="header-anchor" href="#传输选择" aria-label="Permalink to &quot;传输选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传输</th><th>适用</th><th>说明</th></tr></thead><tbody><tr><td><code>http</code></td><td>worker 可被 core 访问</td><td>core 用 <code>http.Client</code> 反向代理，流式转发</td></tr><tr><td><code>stdio</code></td><td>同机、由 core 拉起</td><td><code>mpanel-core</code> spawn <code>mpanel-agent serve</code>，stdin/stdout 走 NDJSON</td></tr><tr><td><code>reverse-ws</code></td><td>NAT/防火墙后、边缘节点</td><td>agent 主动拨号 <code>wss://core/ws/worker</code>，Bearer machine secret 认证</td></tr></tbody></table><h2 id="边缘入网-不走帧" tabindex="-1">边缘入网（不走帧） <a class="header-anchor" href="#边缘入网-不走帧" aria-label="Permalink to &quot;边缘入网（不走帧）&quot;">​</a></h2><p>边缘节点不新增帧类型：agent 先 <code>POST /api/v1/edge/enroll</code>（入网密钥）换取 machine secret， 写入 <code>$MPANEL_AGENT_DATA_DIR/identity.json</code>（0600），随后用既有 <code>/ws/worker</code> 握手拨号。 身份复用，密钥变化或 core 地址变化时重新入网。</p>',11)])])}const E=e(i,[["render",o]]);export{k as __pageData,E as default};
